# PGP keys map for pgpverify-maven-plugin (see pom.xml). Every dependency must match a rule here.
#
# OpenSAML / Shibboleth come from Shibboleth's own repository (not Maven Central), so they are
# pinned to the Shibboleth release key: Philip David Smart (Jisc), fingerprint
# B5B5 DD33 2142 AD65 7E8D 87AC 7D27 E610 B8A3 DC52, as published at
# https://shibboleth.net/downloads/PGP_KEYS. Never add a wildcard that could also match these
# groups: any matching rule is enough for an artifact to pass, which would undo the pin.
org.opensaml = 0xB5B5DD332142AD657E8D87AC7D27E610B8A3DC52
net.shibboleth = 0xB5B5DD332142AD657E8D87AC7D27E610B8A3DC52

# Everything else comes from Maven Central only (.mvn/rrf), and must carry a valid signature by
# any key. A new dependency from an unlisted groupId fails the build ("Not allowed artifact"):
# review it, then add its groupId here.
com.fasterxml.jackson.core = any
com.fasterxml.jackson.datatype = any
com.github.ben-manes.caffeine = any
